### Camera Shake System (Trauma-Based)
```javascript
// In shared/vfx/CameraShake.js
class CameraShake {
    constructor(camera) {
        this.camera = camera;
        this.originalPosition = camera.position.clone();
        this.intensity = 0;      // Current shake magnitude
        this.decayRate = 0.92;   // Per-frame decay factor
        this.duration = 0;       // Remaining frames to shake
    }

    addTrauma(impactVelocity) {
        // Scale intensity by impact velocity (harder hit = more shake)
        const baseIntensity = 0.3;
        const velocityScale = Math.min(impactVelocity, 5.0);
        this.intensity = baseIntensity + (velocityScale * 0.15);
        this.duration = 20 + Math.floor(velocityScale * 4); // Frames to shake
    }

    update() {
        if (this.duration <= 0) return;

        // Perlin-noise-like random offset within intensity sphere
        const angle = Date.now() * 0.015;
        const offsetX = Math.sin(angle) * this.intensity;
        const offsetY = Math.cos(angle * 1.3) * this.intensity;
        const offsetZ = Math.sin(angle * 0.7) * (this.intensity * 0.5);

        this.camera.position.copy(this.originalPosition);
        this.camera.position.add(new Vector3(offsetX, offsetY, offsetZ));

        // Decay intensity over time
        this.intensity *= this.decayRate;
        this.duration--;
    }
}

// Usage in game:
cameraShake.addTrauma(explosionVelocity); // Called on enemy death
