```javascript
// In shared/vfx/HitStop.js
class HitStop {
    constructor() {
        this.isActive = false;
        this.remainingFrames = 0;
        this.totalDuration = 0;
        this.timeScale = 1.0;
    }

    trigger(impactSeverity) {
        // Severity determines freeze duration (3-8 frames typical)
        const baseFrames = 3;
        const severityBonus = Math.floor(impactSeverity * 5);
        this.remainingFrames = baseFrames + severityBonus;
        this.totalDuration = this.remainingFrames;
        this.isActive = true;
    }

    getDeltaTimeMultiplier() {
        if (!this.isActive) return 1.0;

        // During hit-stop, time is frozen (or very slow)
        const freezeAmount = 0.05; // 5% of normal speed during freeze

        this.remainingFrames--;
        if (this.remainingFrames <= 0) {
            this.isActive = false;
        }

        return freezeAmount;
    }
}

// Integration with GameLoop:
const deltaTime = clock.getDelta() * hitStop.getDeltaTimeMultiplier();
