### Particle Manager (Object Pooling + 500 Cap)
```javascript
// In shared/vfx/ParticleManager.js
class ParticleManager {
    constructor(maxParticles = 500) {
        this.maxParticles = maxParticles;
        this.particles = [];      // Active particles
        this.pool = [];           // Object pool for recycling

        // Pre-allocate particle objects
        for (let i = 0; i < maxParticles; i++) {
            const particle = new Particle();
            particle.active = false;
            this.pool.push(particle);
        }
    }

    spawnBurst(position, color, count, velocitySpread) {
        // Enforce hard cap - evict oldest particles if at limit
        while (this.particles.length >= this.maxParticles && this.pool.length === 0) {
            const toEvict = this.particles.shift(); // Remove oldest
            toEvict.active = false;
            this.pool.push(toEvict);
        }

        for (let i = 0; i < count; i++) {
            let particle;

            if (this.pool.length > 0) {
                particle = this.pool.pop();
            } else {
                particle = new Particle();
            }

            // Initialize burst parameters
            particle.position.copy(position);
            particle.color.set(color);
            particle.velocity.set(
                (Math.random() - 0.5) * velocitySpread,
                (Math.random() - 0.5) * velocitySpread,
                (Math.random() - 0.5) * velocitySpread
            );
            particle.lifetime = 1.0 + Math.random() * 0.5; // Seconds
            particle.maxLifetime = particle.lifetime;
            particle.active = true;

            this.particles.push(particle);
        }
    }

    update(deltaTime) {
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];

            // Update position
            p.position.addScaledVector(p.velocity, deltaTime);

            // Apply gravity/drag
            p.velocity.multiplyScalar(0.98); // Air resistance

            // Decay lifetime
            p.lifetime -= deltaTime;

            if (p.lifetime <= 0) {
                // Recycle particle
                p.active = false;
                this.particles.splice(i, 1);
                this.pool.push(p);
            }
        }
    }

    render(renderer) {
        // Use InstancedMesh for performance
        const activeCount = this.particles.length;

        if (this.instancedMesh === null || this.instancedMesh.count !== activeCount) {
            this.createInstancedMesh(activeCount);
        }

        // Update instance matrices and colors
        let dummy = new Object3D();
        for (let i = 0; i < activeCount; i++) {
            const p = this.particles[i];
            dummy.position.copy(p.position);
            dummy.scale.setScalar(p.lifetime / p.maxLifetime); // Fade out
            dummy.updateMatrix();

            this.instancedMesh.setMatrixAt(i, dummy.matrix);
            this.instancedMesh.setColorAt(i, p.color);
        }

        this.instancedMesh.instanceMatrix.needsUpdate = true;
    }

    dispose() {
        // Clean up all resources
        if (this.instancedMesh) {
            this.instancedMesh.geometry.dispose();
            this.instancedMesh.material.dispose();
            this.instancedMesh = null;
        }
    }
}
