```javascript
// In shared/vfx/MotionTrails.js
class MotionTrails {
    constructor(maxTrailLength = 10) {
        this.maxLength = maxTrailLength;
        this.trailObjects = new Map(); // Object3D -> TrailData[]
    }

    addTarget(object, color, trailWidth = 0.1) {
        if (!this.trailObjects.has(object)) {
            this.trailObjects.set(object, {
                positions: [],
                color: new Color(color),
                width: trailWidth,
                mesh: null
            });

            // Create trail geometry (line segments)
            const geom = new BufferGeometry();
            const maxPoints = this.maxLength * 3; // 3 points per segment

            geom.setAttribute('position', new Float32BufferAttribute(maxPoints * 3, maxPoints * 3));
            geom.setAttribute('color', new Float32BufferAttribute(maxPoints * 3, maxPoints * 3));

            const material = new LineBasicMaterial({
                vertexColors: true,
                transparent: true,
                opacity: 0.8
            });

            const trailMesh = new LineSegments(geom, material);
            object.parent.add(trailMesh); // Add to scene via parent
        }
    }

    update() {
        for (const [object, data] of this.trailObjects) {
            if (!object.visible) continue;

            // Record current position
            data.positions.push(object.position.clone());

            // Trim old positions
            while (data.positions.length > this.maxLength) {
                data.positions.shift();
            }

            // Update trail mesh geometry
            const positions = data.mesh.geometry.attributes.position.array;
            const colors = data.mesh.geometry.attributes.color.array;

            let index = 0;
            for (let i = 0; i < data.positions.length - 1; i++) {
                const alpha = i / data.positions.length; // Fade at tail

                positions[index++] = data.positions[i].x;
                positions[index++] = data.positions[i].y;
                positions[index++] = data.positions[i].z;

                positions[index++] = data.positions[i + 1].x;
                positions[index++] = data.positions[i + 1].y;
                positions[index++] = data.positions[i + 1].z;

                const r = data.color.r;
                const g = data.color.g;
                const b = data.color.b;

                colors[index - 6] = r; colors[index - 5] = g; colors[index - 4] = b * alpha;
                colors[index - 3] = r; colors[index - 2] = g; colors[index - 1] = b * alpha;
            }

            data.mesh.geometry.attributes.position.needsUpdate = true;
            data.mesh.geometry.attributes.color.needsUpdate = true;
        }
    }
}
