// In shared/vfx/ShockwaveRings.js
class ShockwaveManager {
    constructor(maxRings = 20) {
        this.maxRings = maxRings;
        this.rings = [];

        // Create InstancedMesh for all rings (torus geometry)
        const geometry = new TorusGeometry(1, 0.05, 8, 32);
        const material = new MeshBasicMaterial({
            color: 0xffffff,
            transparent: true,
            opacity: 1.0,
            side: DoubleSide
        });

        this.instancedMesh = new InstancedMesh(geometry, material, maxRings);
        this.instancedMesh.instanceMatrix.setUsage(StaticDrawUsage);
    }

    spawn(position, color, expandSpeed = 2.0) {
        if (this.rings.length >= this.maxRings) {
            // Evict oldest ring
            const oldRing = this.rings.shift();
            oldRing.visible = false;
        }

        const ring = {
            position: position.clone(),
            color: new Color(color),
            expandSpeed: expandSpeed,
            radius: 0.1,
            maxRadius: 3.0,
            opacity: 1.0,
            instanceId: this.rings.length,
            visible: true
        };

        this.rings.push(ring);
    }

    update(deltaTime) {
        let dummy = new Object3D();
        let activeCount = 0;

        for (const ring of this.rings) {
            if (!ring.visible) continue;

            // Expand radius
            ring.radius += ring.expandSpeed * deltaTime;

            // Fade out as it expands
            ring.opacity = 1.0 - (ring.radius / ring.maxRadius);

            if (ring.radius >= ring.maxRadius || ring.opacity <= 0) {
                ring.visible = false;
                continue;
            }

            // Update instance matrix
            dummy.position.copy(ring.position);
            dummy.scale.set(ring.radius, ring.radius, 1);
            dummy.rotation.x = Math.PI / 2; // Lay flat on ground plane
            dummy.updateMatrix();

            this.instancedMesh.setMatrixAt(activeCount, dummy.matrix);

            // Update color with opacity
            const rgba = new Color(ring.color).convertLinearToSRGB().getRGB();
            this.instancedMesh.setColorAt(activeCount, ring.color);

            activeCount++;
        }

        this.instancedMesh.count = activeCount;
        this.instancedMesh.instanceMatrix.needsUpdate = true;
    }
}
